// Papierkram-Zugang aus der Oberfläche (Seite Unternehmen, nur Admins). Aufbau wie ALLY 11 (Stefan 17.10.2026).
// Herkunft prüfen wie bei ALLY 8, Sitzung aus dem Cookie. Der API-Schlüssel geht nur an den Prüfabruf und an die
// n8n-Zugangsdaten (beide lesen ihn selbst aus dem Formular), nie in die Datenbank und nicht in diese Ausgabe.
// Dieser Ablauf speichert keine Ausführungsdaten.
// Eigene Adresse aus der Anfrage (Host-Kopfzeile, von traefik unverändert weitergegeben), keine festen Werte.
const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(($json.headers || {}).host || '').trim().toLowerCase());
const h = $json.headers || {};
const b = $json.body || {};
const herkunft = String(h.origin || '');
const verweis = String(h.referer || '');
// Verweis muss genau auf die Seite zeigen, danach nur Ende, '/', '?' oder '#' (nicht z. B. /webhook/web-fremd)
const SEITE_PFAD = HOST + '/webhook/web';
const vonSeite = HOST !== '' && verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
const herkunftOk = HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite));
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const subdomain = String(b.subdomain ?? '').trim().toLowerCase();
// Nur ob ein neuer Schlüssel kam, nicht der Schlüssel selbst
const neu = String(b.schluessel ?? '').trim() !== '';
const daten = { subdomain, schluessel: neu ? 'neu' : '' };
return [{ json: { token, herkunft: herkunftOk ? 'ok' : 'ungueltig', neu, daten: JSON.stringify(daten) } }];

// Prüfabruf auswerten (Stefan 17.10.2026): test_ok und eine kurze Meldung, nie der Schlüssel.
// Fehlertexte von n8n werden nicht übernommen, nur der Fehlercode (z. B. ENOTFOUND).
const neu = $('Formular prüfen').first().json.neu === true;
const knoten = neu ? 'Papierkram prüfen (neuer Schlüssel)' : 'Papierkram prüfen (gespeichert)';
const r = $(knoten).isExecuted ? ($(knoten).first().json || {}) : {};
const st = Number(r.statusCode) || 0;
const welcher = neu ? 'Der API-Schlüssel' : 'Der gespeicherte API-Schlüssel';
let test_ok = false, meldung = '';
if (!st) {
  // Fehler kann Objekt oder Text sein; nur einen bekannten Fehlercode herausziehen
  const e = r.error || {};
  const text = typeof e === 'string' ? e : String(e.message || e.description || '');
  const code = String((typeof e === 'object' && (e.code || (e.cause && e.cause.code))) || (text.match(/\b(E[A-Z_]{2,28}|CERT_[A-Z_]{2,25})\b/) || [])[1] || '');
  if (code === 'ENOTFOUND') meldung = 'Papierkram ist unter dieser Subdomain nicht erreichbar. Bitte die Subdomain prüfen.';
  else if (['ETIMEDOUT', 'ECONNABORTED', 'ESOCKETTIMEDOUT'].includes(code)) meldung = 'Papierkram hat nicht rechtzeitig geantwortet. Bitte später erneut versuchen.';
  else meldung = 'Papierkram ist nicht erreichbar' + (/^[A-Z_]{3,30}$/.test(code) ? ' (' + code + ')' : '') + '.';
} else if (st === 200) {
  const body = r.body;
  if (body && typeof body === 'object' && !Array.isArray(body)) test_ok = true;
  else meldung = 'Papierkram antwortet nicht wie erwartet. Bitte die Subdomain prüfen.';
} else if (st === 401 || st === 403) meldung = welcher + ' wird von Papierkram abgelehnt (Status ' + st + '). Bitte in Papierkram unter Einstellungen > API prüfen.';
else if (st === 404) meldung = 'Unter dieser Subdomain gibt es keine Papierkram-API (Status 404). Bitte die Subdomain prüfen.';
else if (st >= 300 && st < 400) meldung = 'Papierkram leitet die Anfrage um (Status ' + st + '). Bitte die Subdomain prüfen.';
else if (st === 429) meldung = 'Zu viele Anfragen an Papierkram. Bitte später erneut versuchen.';
else meldung = 'Unerwartete Antwort von Papierkram (Status ' + st + ').';
return [{ json: { test_ok, meldung } }];

// Zurück auf die Seite Unternehmen (Stefan 17.10.2026); Sitzung wie bei ALLY 8 behandeln
const SEITE = '/webhook/web';
const F = $('Formular prüfen').first().json;
// Stelle auf der Seite: Position, offene Bereiche und Formular aus der Adresse des Formulars wieder anhängen, damit die Seite nicht nach oben springt (wie ALLY 11)
const ZQ = $('Formular').first().json.query || {};
const stelle = ziel => { const y = String(ZQ.zy || ''), o = String(ZQ.zo || ''), f = String(ZQ.zf || ''), t = String(ZQ.zt || '');
  if (!/^[0-9]{1,6}$/.test(y)) return ziel;
  const z = ziel.split('#')[0], s = 'zy=' + y + (/^[0-9]{1,3}(\.[0-9]{1,3}){0,39}$/.test(o) ? '&zo=' + o : '') + (/^[A-Za-z0-9_-]{0,60}~[0-9]{1,3}$/.test(f) ? '&zf=' + f + (/^-?[0-9]{1,5}$/.test(t) ? '&zt=' + t : '') : '');
  return z + (z.includes('?') ? '&' : '?') + s; };
const r = ($('Abschließen').isExecuted ? $('Abschließen').first().json.r : $('Vorbereiten').first().json.v) || {};
const keks = (wert, alter) => 'ally_sitzung=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=None';
let ziel, cookie = '';
if (F.herkunft !== 'ok' || r.ungueltig) ziel = SEITE + '?m=ungueltig';
else if (r.angemeldet === false) { ziel = SEITE + '?m=abgelaufen'; cookie = keks('', 0); }
else { ziel = stelle(SEITE + '?ansicht=unternehmen'); if (F.token) cookie = keks(F.token, 2592000); }
return [{ json: { ziel, set_cookie: cookie } }];

// Ergebnis für "Abschließen" zusammenfassen (Stefan 17.10.2026), ohne Schlüssel.
// Ist der Schlüssel gültig, konnte aber nicht in n8n gespeichert werden, gilt die Prüfung als nicht bestanden.
const F = $('Formular prüfen').first().json;
const V = $('Vorbereiten').first().json.v || {};
const P = $('Prüfung auswerten').first().json || {};
let test_ok = P.test_ok === true;
let meldung = String(P.meldung || '');
if ($('Zugangsdaten setzen').isExecuted) {
  const r = $('Zugangsdaten setzen').first().json || {};
  const st = Number(r.statusCode) || 0;
  if (st !== 200) {
    test_ok = false;
    meldung = 'Der API-Schlüssel ist gültig, konnte aber nicht in n8n gespeichert werden (' + (st ? 'Status ' + st : 'keine Antwort') + ').';
  }
}
let subdomain = String(V.subdomain || '');
if (!subdomain) { try { subdomain = String(JSON.parse(F.daten).subdomain || ''); } catch (e) { subdomain = ''; } }
return [{ json: { token: F.token, daten: JSON.stringify({ subdomain }), ergebnis: JSON.stringify({ test_ok, meldung: meldung.slice(0, 300) }) } }];
